// Controller independent public API/lexical checks; no fixture writes or traversal.
#![forbid(unsafe_code)]
use serde_json::Value;
use water_contracts::v1::OpaqueId;
use water_native_root::v1::{self as n,RootError};
fn index()->Value{serde_json::from_str(&std::fs::read_to_string(std::env::var("WATER_NATIVE_ROOT_FIXTURE_INDEX").unwrap()).unwrap()).unwrap()}
#[test]fn independent_path_matrix(){
 for drive in ['A','f','Z']{for sep in ['/', '\\']{for stem in ["CON","con","Nul","PRN","aux","CONIN$","ConOut$","COM1","COM9","LPT1","lpt9","COM¹","LPT²","COM³"]{for suffix in ["",".txt"," .txt",".a.b"]{assert_eq!(n::validate_windows_path(&format!("{drive}:{sep}safe{sep}{stem}{suffix}")),Err(RootError::InvalidPath));}}}}
 for base in ["C:/a", "f:\\项目", "Z:/😀", "A:/a/.git/COM0"]{assert!(n::validate_windows_path(base).is_ok());for tail in ["/", "\\", "/.", "/..", "/file.", "/file ", ":ads", "//x", "/a?b", "/a*b", "/a|b", "/a<b", "/a>b", "/a\"b"]{assert_eq!(n::validate_windows_path(&format!("{base}{tail}")),Err(RootError::InvalidPath));}}
 for c in (0..=31).chain(Some(127)){let c=char::from_u32(c).unwrap();assert_eq!(n::validate_windows_path(&format!("C:/a{c}b")),Err(RootError::InvalidPath));}
 assert!(n::validate_windows_path(&format!("C:/{}", "😀".repeat(118))).is_ok());assert_eq!(n::validate_windows_path(&format!("C:/{}", "😀".repeat(119))),Err(RootError::InvalidPath));
}
#[test]fn independent_native_identity_and_scope(){let i=index();let id=OpaqueId::new("independent-identity").unwrap();let mut values=Vec::new();for key in ["normal_a","normal_b","nested"]{let lease=n::open_directory(&id,i[key].as_str().unwrap()).unwrap();let first=lease.observation().clone();assert_eq!(first,lease.refresh().unwrap());let wire:Value=serde_json::from_str(&n::to_json(&first).unwrap()).unwrap();assert_eq!(wire["scope_id"],id.as_str());assert!(!first.authorization_granted()&&!first.traversal_allowed()&&!first.race_protection_verified());assert_eq!(wire.as_object().unwrap().len(),10);let again=n::open_directory(&OpaqueId::new("other-scope").unwrap(),i[key].as_str().unwrap()).unwrap();assert_eq!(first.identity(),again.observation().identity());values.push(wire["identity"].clone());}assert_ne!(values[0],values[1]);assert_ne!(values[0],values[2]);assert_ne!(values[1],values[2]);}
#[test]fn independent_reparse_and_error_order(){let i=index();let id=OpaqueId::new("independent-errors").unwrap();for key in ["final_reparse","ancestor_reparse","ancestor_child"]{assert!(matches!(n::open_directory(&id,i[key].as_str().unwrap()),Err(RootError::ReparsePoint)));}for (key,expected)in [("file",RootError::NotDirectory),("missing",RootError::MetadataUnavailable)]{let e=n::open_directory(&id,i[key].as_str().unwrap()).err().unwrap();assert_eq!(e,expected);assert_eq!(e.to_string(),format!("{e:?}"));assert!(std::error::Error::source(&e).is_none());}for invalid in ["C:/", "\\\\host\\share", "C:relative", "C:/bad/../CANARY", "C:/CON .txt"]{assert!(matches!(n::open_directory(&id,invalid),Err(RootError::InvalidPath)));}}
